    engineFlow: [["ROVE", "생태계와 합의"], ["USDT 참여 자금", "실제 참여가 만드는 매수세"], ["BUYBACK & BURN", "프로토콜 환매와 직접 소각"], ["DEFLATION ENGINE", "공급 지속 축소"]],
